$('#writing-material-summary')?.addEventListener('click',e=>{const button=e.target.closest('[data-knowledge-action]');if(button?.dataset.knowledgeAction==='remove'){const id=button.dataset.knowledgeId;knowledgeFiles=knowledgeFiles.filter(item=>String(item.id)!==String(id));if(knowledgeFiles.length)syncKnowledgeMaterial();else{material='';fileName='';materialState='saved';$('#writing-material').value='';}$('#material-status').textContent='资料已移除，请保存草稿以更新。';renderMaterial();}});$('#knowledge-ai-generate')?.addEventListener('click',()=>{const input=$('#knowledge-ai-input'),status=$('#knowledge-ai-status'),text=input?.value.trim()||'';if(!text){if(status)status.textContent='请先描述你的研究背景、方法或创新点。';input?.focus();return;}knowledgeFiles=knowledgeFiles.filter(item=>item.kind!=='ai');knowledgeFiles.push({id:knowledgeId(),name:taskKind==='writing'?'用户研究说明':'AI 补充说明',purpose:taskKind==='writing'?'研究背景与方法':'AI 补充',text,state:'edited',kind:'ai'});syncKnowledgeMaterial();if(status)status.textContent='已记录补充说明，确认后将用于后续提纲。';renderMaterial();});document.querySelectorAll('.knowledge-upload-trigger').forEach(button=>button.addEventListener('click',()=>{const purpose=button.dataset.purpose,select=$('#material-purpose');if(select)select.value=purpose==='proposal'?'导师要求':purpose==='format'?'格式要求':'已有草稿';$('#writing-file')?.click();}));function renderMaterial(){$('#material-file-card').hidden=!material;$('#material-file-card').innerHTML=material?`<div><b>${esc(fileName||'参考材料')}</b><small>${materialState==='parsed'?'已解析':materialState==='edited'?'正文已编辑':'已保存材料'} · ${material.length.toLocaleString('zh-CN')} 字符</small></div><button type="button" id="material-card-remove" aria-label="移除参考材料">×</button>`:'';if(material)$('#material-card-remove').addEventListener('click',()=>$('#material-remove').click());render();}
