$('#outline-confirm').addEventListener('click',()=>{sync();if(!outlineRowsReady)ensureOutlineRows();if(workflowStage===4&&!outlineConfirmed&&outlineRowsReady)syncOutlineRowsToContent();if(!content.trim())return;const empty=outlineRows.findIndex(row=>!String(row.title||'').trim()),target=Number($('#writing-target')?.value||0),total=outlineTotalWords();if(empty>=0){$('#writing-status').textContent=`第 ${empty+1} 行标题不能为空，请补充后再确认。`;document.querySelectorAll('#outline-paper .outline-edit-row')[empty]?.querySelector('.outline-row-title')?.focus();return;}if(!outlineRows.some(row=>row.level===1)){$('#writing-status').textContent='提纲至少需要保留一个章节，请新增章节后再确认。';return;}if(target&&total>target){$('#writing-status').textContent=`提纲分配已超过目标字数 ${target.toLocaleString('zh-CN')} 字，请先调整。`;return;}if(outlineRowsReady&&outlineRows.some(row=>row.level===1)){const previous=new Map(bodySections.map(section=>[String(section.title||''),section]));const next=outlineRows.filter(row=>row.level===1).map(row=>{const old=previous.get(String(row.title||''));return {id:row.id,title:String(row.title||'未命名章节'),text:old?.text||''};});bodySections=taskKind==='writing'?[...next,...bodySections.filter(section=>!next.some(row=>row.title===section.title)&&String(section.text||'').trim()).map(section=>({...section,retained:true}))]:next;}else bodySections=reconcileSections(content,bodySections);outlineConfirmed=true;editing=false;$('#outline-editor').hidden=true;$('#outline-paper').hidden=false;$('#outline-edit').textContent='✎　编辑大纲';if(taskKind==='writing'){workflowStage=5;showExport();$('#writing-status').textContent='提纲已确认，请保存到账户并确认资料与费用后生成。';}else if(isStructured){workflowStage=5;showExport();$('#preview-tag').textContent='待解锁下载';$('#writing-status').textContent=`${kindLabel}提纲已确认，可进入生成版本确认。`;}else{workflowStage=4;showBody();$('#preview-tag').textContent='手动写作';$('#writing-status').textContent='大纲已确认，可逐章填写正文；请保存以保留进度。';}});
