function updateExportGate(){syncWritingUnlock();const hasBody=bodySections.some(s=>s.text.trim()),available=exportUnlocked&&(isStructured?outlineConfirmed:hasBody),badge=$('#writing-unlock-badge'),lock=$('#writing-version-lock'),recharge=$('#writing-version-recharge'),unlocked=$('#writing-version-unlocked'),downloads=$('#writing-version-downloads'),note=$('#writing-version-payment-note');if(badge){badge.textContent=exportUnlocked?'已解锁':'未解锁';badge.classList.toggle('is-locked',!exportUnlocked);badge.classList.toggle('is-unlocked',exportUnlocked);}if(lock)lock.hidden=exportUnlocked;if(recharge)recharge.hidden=exportUnlocked;if(unlocked)unlocked.hidden=!exportUnlocked;if(downloads)downloads.classList.toggle('is-ready',available);for(const id of ['body-export','body-docx','body-pdf']){const button=$('#'+id);if(button)button.disabled=!available;}if(note)note.textContent=exportUnlocked?(isStructured?`已解锁当前版本，可下载${kindLabel}并核对最终格式。`:hasBody?'已解锁当前版本，可下载并核对最终格式。':'已解锁；请先填写至少一章正文后再下载。'):'支付与自动解锁尚未开放。请先保存草稿，已填写内容会继续保留在当前浏览器。';}
function renderExportPreview(){const preview=$('#writing-version-preview');if(!preview)return;const v=values();ensureOutlineRows();const rows=outlineRows.length?outlineRows:parseOutlineRows(content),target=Number(v.targetWords||0),total=rows.reduce((sum,row)=>sum+(Number(row.words)||0),0),filled=bodySections.filter(s=>s.text.trim()).length,bodyPreview=composeBody(v,bodySections);if($('#body-preview'))$('#body-preview').textContent=bodyPreview;preview.innerHTML=`<div class="writing-preview-paper"><div class="writing-preview-title">${esc(v.title||(isStructured?'未填写题目':'未填写论文题目'))}</div><div class="writing-preview-subtitle">目录 · ${esc(v.degree||'学历待填写')} · ${esc(v.major||'专业待填写')}</div><div class="writing-preview-divider"></div><div class="writing-preview-outline">${rows.map(row=>`<div class="writing-preview-row ${row.level===1?'is-chapter':'is-subsection'}"><span>${row.level===1?'章节':'小节'}</span><b>${esc(row.title||'未命名章节')}</b>${row.words?`<em>${Number(row.words).toLocaleString('zh-CN')} 字</em>`:''}</div>`).join('')}</div><div class="writing-preview-skeleton"><i></i><i></i><i></i></div></div>`;$('#writing-version-meta').textContent=isStructured?`${rows.length} 个结构节点 · 提纲已确认`:`${rows.length} 个结构节点 · ${filled}/${bodySections.length||rows.filter(row=>row.level===1).length} 章已填写`;$('#writing-version-degree').textContent=v.degree||'学历待填写';$('#writing-version-summary').innerHTML=`<div><span>目标字数</span><b>${target?target.toLocaleString('zh-CN')+' 字':'未设置'}</b></div><div><span>已分配字数</span><b>${total?total.toLocaleString('zh-CN')+' 字':'待分配'}</b></div><div><span>参考文献</span><b>${writingReferences.length} 篇</b></div><div><span>格式模板</span><b title="${esc(formatTemplateName||'未设置')}">${esc(formatTemplateName||'未设置')}</b></div>`;document.querySelectorAll('[data-version-plan]').forEach(button=>button.classList.toggle('is-selected',button.dataset.versionPlan===writingVersionPlan));const plan=writingVersionPlans[writingVersionPlan]||writingVersionPlans.advanced;const recharge=$('#writing-version-recharge');if(recharge)recharge.textContent=`${plan.label}导出服务 · ${plan.price}`;updateExportGate();}
function ensureThesisStage(){if(taskKind!=='writing'||thesisStageDispose||disposed)return;thesisStageDispose=mountThesisStage({container:$('#thesis-online-stage'),ctx:ctx||{},id:thesisId,getSnapshot:()=>{sync();ensureOutlineRows();return thesisSnapshotFromDraft({...values(),knowledgeFiles,writingReferences,outlineRows,bodySections,material,fileName,formatTemplateName});},onSaved:id=>{thesisId=id;$('#writing-save')?.click();},onManual:()=>{thesisStageDispose?.();thesisStageDispose=null;workflowStage=4;showBody();$('#writing-status').textContent='继续本地手动写作；账户内容独立保存。';}});}
