if(outlineConfirmed){if(taskKind==='writing'&&workflowStage===5){showExport();}else if(isStructured){workflowStage=5;showExport();}else{if(!bodySections.length)bodySections=reconcileSections(content);showBody();}}renderMaterial();
$('#outline-editor').addEventListener('input',()=>{$('#writing-status').textContent='大纲已修改，请完成编辑并保存。';});
$('#writing-form').addEventListener('submit',e=>{e.preventDefault();if(parsing)return;const v=values();if(v.title.length<2){$('#writing-error').textContent='请填写至少 2 个字的论文题目或研究方向。';$('#writing-title').focus();return;}if(!practiceDatesValid(v)){$('#writing-error').textContent='结束日期不能早于开始日期，请检查实践周期。';$('#practice-end')?.focus();return;}$('#writing-error').textContent='';if(content&&!window.confirm('重新生成会替换当前大纲。已有章节正文会保留，确认后请核对章节关联。'))return;content=buildTaskOutline(v);outlineSource='ai';outlineState='generated';outlineFileName='';outlineConfirmed=false;workflowStage=3;editing=false;$('#outline-editor').hidden=true;$('#outline-paper').hidden=false;$('#outline-edit').textContent='✎　编辑大纲';$('#preview-tag').textContent='本地模板';render();$('#writing-status').textContent='大纲模板已生成，可编辑、保存和导出。';});
$('#outline-edit').addEventListener('click',()=>{if(!content)return;outlineConfirmed=false;workflowStage=4;outlineSource=outlineSource||'pasted';outlineState='edited';updateWorkflow();if(editing){sync();editing=false;render();}else{editing=true;$('#outline-editor').value=content;}$('#outline-editor').hidden=!editing;$('#outline-paper').hidden=editing;if(editing)$('#outline-editor').focus();$('#outline-edit').textContent=editing?'完成编辑':'✎　编辑大纲';});
